"""Reclaim database storage taken up by system logs and auto-generated history.

Removes roughly 700 MB of non-business data and then rebuilds the affected
tables so the space is actually returned to the filesystem.

Nothing in this patch touches accounting, stock, invoice, payment or item
records. Only logs, change history and auto-generated audit rows are removed.

IMPORTANT: deleting rows from InnoDB does not shrink the table files on its
own -- the freed pages stay reserved by the tablespace. Tables that are emptied
entirely use TRUNCATE (which recreates the tablespace and reclaims immediately);
tables that are only partly cleared are rebuilt afterwards with OPTIMIZE TABLE.
Without that rebuild the reported database size does not move at all.
"""

import frappe

# --- configuration -----------------------------------------------------------

# Keep this many days of document change history / deleted-document archive.
VERSION_RETENTION_DAYS = 90
DELETED_DOCUMENT_RETENTION_DAYS = 90
LOG_RETENTION_DAYS = 90

# Rows deleted per batch. Keeps transactions short and avoids long table locks.
BATCH_SIZE = 10000

# The search index regenerates for documents as they are saved. Truncating it
# frees ~90 MB immediately but site-wide search stays incomplete until a full
# rebuild is run. Set to False to leave the index alone.
TRUNCATE_GLOBAL_SEARCH = True

# Repost Item Valuation rows in these statuses are removed.
# "Failed" is included: those reposts will never complete on their own. Note
# that deleting them also discards the record that a valuation was never
# recalculated, and the ability to retry it -- so the count is logged first.
# Queued / In Progress are never deleted; they are still pending work.
REPOST_STATUSES_TO_DELETE = ("Completed", "Skipped", "Failed")

# Emptied completely -- TRUNCATE reclaims space without needing a rebuild.
TRUNCATE_TABLES = [
	"tabAccess Log",
	"tabData Import Log",
	"tabRoute History",
]

# Trimmed to LOG_RETENTION_DAYS, then rebuilt.
LOG_TABLES = [
	"tabError Log",
	"tabActivity Log",
	"tabScheduled Job Log",
	"tabNotification Log",
	"tabPermission Log",
]


# --- helpers -----------------------------------------------------------------

def _log(msg):
	print(f"[reclaim_database_storage] {msg}")


def _table_exists(table):
	return bool(frappe.db.sql("SHOW TABLES LIKE %s", (table,)))


def _size_mb(table=None):
	"""Size of one table, or of the whole database when table is None."""
	if table:
		row = frappe.db.sql(
			"""SELECT ROUND((data_length + index_length) / 1048576, 2)
			   FROM information_schema.tables
			   WHERE table_schema = %s AND table_name = %s""",
			(frappe.conf.db_name, table),
		)
	else:
		row = frappe.db.sql(
			"""SELECT ROUND(SUM(data_length + index_length) / 1048576, 2)
			   FROM information_schema.tables WHERE table_schema = %s""",
			(frappe.conf.db_name,),
		)
	return (row and row[0][0]) or 0


def _delete_in_batches(table, where, params=()):
	"""Delete by primary key in batches so the undo log stays small."""
	removed = 0
	while True:
		names = frappe.db.sql(
			f"SELECT `name` FROM `{table}` WHERE {where} LIMIT {BATCH_SIZE}",
			params,
			pluck=True,
		)
		if not names:
			break
		frappe.db.sql(f"DELETE FROM `{table}` WHERE `name` IN %s", (tuple(names),))
		frappe.db.commit()
		removed += len(names)
	return removed


def _truncate(table):
	frappe.db.sql(f"TRUNCATE TABLE `{table}`")
	frappe.db.commit()


def _rebuild(table):
	"""OPTIMIZE TABLE on InnoDB performs a full table rebuild, which is what
	actually returns the freed pages to the filesystem."""
	frappe.db.sql(f"OPTIMIZE TABLE `{table}`")
	frappe.db.commit()


# --- patch -------------------------------------------------------------------

def execute():
	if frappe.db.db_type != "mariadb":
		_log(f"skipped: only supported on MariaDB (found {frappe.db.db_type})")
		return

	before_total = _size_mb()
	_log(f"database size before: {before_total} MB")

	rebuild_targets = []

	# 1. Attachment log entries generated by the stock valuation repost process.
	#    These carry no content; genuine user comments are left untouched.
	_step(
		"tabComment",
		lambda: _delete_in_batches(
			"tabComment",
			"comment_type IN ('Attachment', 'Attachment Removed') "
			"AND reference_doctype = 'Repost Item Valuation'",
		),
		rebuild_targets,
	)

	# 2. Stock valuation reposts in a terminal state (see
	#    REPOST_STATUSES_TO_DELETE). Queued / In Progress rows are kept because
	#    they are still pending work.
	_warn_failed_reposts()
	_step(
		"tabRepost Item Valuation",
		lambda: _delete_in_batches(
			"tabRepost Item Valuation",
			"status IN %s",
			(tuple(REPOST_STATUSES_TO_DELETE),),
		),
		rebuild_targets,
	)
	_report_retained_reposts()

	# 3. Document change history older than the retention window.
	_step(
		"tabVersion",
		lambda: _delete_in_batches(
			"tabVersion",
			"creation < NOW() - INTERVAL %s DAY",
			(VERSION_RETENTION_DAYS,),
		),
		rebuild_targets,
	)

	# 4. Deleted-document archive older than the retention window.
	_step(
		"tabDeleted Document",
		lambda: _delete_in_batches(
			"tabDeleted Document",
			"creation < NOW() - INTERVAL %s DAY",
			(DELETED_DOCUMENT_RETENTION_DAYS,),
		),
		rebuild_targets,
	)

	# 5. Assorted system logs, trimmed to the retention window.
	for table in LOG_TABLES:
		_step(
			table,
			lambda t=table: _delete_in_batches(
				t, "creation < NOW() - INTERVAL %s DAY", (LOG_RETENTION_DAYS,)
			),
			rebuild_targets,
		)

	# 6. Tables emptied completely. TRUNCATE reclaims space with no rebuild.
	for table in TRUNCATE_TABLES:
		_truncate_step(table)

	if TRUNCATE_GLOBAL_SEARCH:
		_truncate_step("__global_search")

	# 7. Rebuild every partially-cleared table so the space is released.
	for table in rebuild_targets:
		try:
			freed_from = _size_mb(table)
			_rebuild(table)
			_log(f"rebuilt {table}: {freed_from} MB -> {_size_mb(table)} MB")
		except Exception as e:
			_log(f"rebuild failed for {table}: {e}")

	after_total = _size_mb()
	_log(f"database size after: {after_total} MB (reclaimed {round(before_total - after_total, 2)} MB)")


def _warn_failed_reposts():
	"""Record how many Failed reposts are about to be removed.

	A Failed repost means a stock valuation was never recalculated. Deleting the
	row frees space but discards both that signal and the chance to retry it, so
	the count is written to the migrate output before anything is removed.
	"""
	if "Failed" not in REPOST_STATUSES_TO_DELETE:
		return
	if not _table_exists("tabRepost Item Valuation"):
		return
	try:
		count = frappe.db.sql(
			"SELECT COUNT(*) FROM `tabRepost Item Valuation` WHERE status = 'Failed'"
		)[0][0]
		if count:
			_log(
				f"WARNING: removing {count} Failed repost(s). Those stock valuations "
				"were never recalculated and can no longer be retried from these rows."
			)
	except Exception as e:
		_log(f"could not count Failed reposts: {e}")


def _report_retained_reposts():
	"""Surface repost rows this patch deliberately did not delete.

	Queued / In Progress rows are pending work; Failed rows mean a valuation was
	never recalculated and needs attention. Either way they are left alone, so
	they are reported rather than silently skipped.
	"""
	if not _table_exists("tabRepost Item Valuation"):
		return
	try:
		rows = frappe.db.sql(
			"""SELECT status, COUNT(*) FROM `tabRepost Item Valuation`
			   GROUP BY status ORDER BY COUNT(*) DESC"""
		)
		if rows:
			kept = ", ".join(f"{status}: {count}" for status, count in rows)
			_log(f"tabRepost Item Valuation retained -> {kept}")
		else:
			_log("tabRepost Item Valuation retained -> none")
	except Exception as e:
		_log(f"could not report retained reposts: {e}")


def _step(table, fn, rebuild_targets):
	"""Run one delete step, tolerating failure so migrate is never blocked."""
	if not _table_exists(table):
		_log(f"skipped {table}: table not present")
		return
	try:
		removed = fn()
		_log(f"{table}: removed {removed} rows")
		if removed:
			rebuild_targets.append(table)
	except Exception as e:
		frappe.db.rollback()
		_log(f"failed on {table}: {e}")


def _truncate_step(table):
	if not _table_exists(table):
		_log(f"skipped {table}: table not present")
		return
	try:
		before = _size_mb(table)
		_truncate(table)
		_log(f"truncated {table}: freed {before} MB")
	except Exception as e:
		frappe.db.rollback()
		_log(f"failed to truncate {table}: {e}")
